        PATH_ComputeMovementStep((uint32_t*)&sNewPos, (uint32_t*)&pUnit, pDynamicPath);
        DRLGPATH_SetPathPosition(sNewPos.nX, sNewPos.nY, nullptr, pDynamicPath);
